import{_ as d,o as r,a as i,b as p}from"./app.C41L12d5.js";const I=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"高阶API","link":"/api/SIMD-API/adv_api/adv_api"},{"text":"卷积计算","link":"/api/SIMD-API/adv_api/convolution_compute/convolution_compute"},{"text":"Conv3DBackpropInput Tiling侧接口","link":"/api/SIMD-API/adv_api/convolution_compute/Conv3DBackpropInput_Tiling/Conv3DBackpropInput_Tiling"},{"text":"TConv3DBackpropInputTiling结构体","link":"/api/SIMD-API/adv_api/convolution_compute/Conv3DBackpropInput_Tiling/TConv3DBackpropInputTiling_struct"}]},"headers":[],"relativePath":"api/SIMD-API/adv_api/convolution_compute/Conv3DBackpropInput_Tiling/TConv3DBackpropInputTiling_struct.md","filePath":"api/SIMD-API/adv_api/convolution_compute/Conv3DBackpropInput_Tiling/TConv3DBackpropInputTiling_struct.md","lastUpdated":1787050286000}'),n={name:"api/SIMD-API/adv_api/convolution_compute/Conv3DBackpropInput_Tiling/TConv3DBackpropInputTiling_struct.md"};function a(e,t,o,u,l,c){return r(),i("div",null,[...t[0]||(t[0]=[p('<div><article class="markdown-body"><h1>TConv3DBackpropInputTiling结构体</h1><p>TConv3DBackpropInputTiling结构体包含Conv3DBackpropInput算子规格信息及Tiling切分算法的相关参数，被传递给Conv3DBackpropInput核函数（Kernel）侧，用于数据切分、数据搬运和计算等。TConv3DBackpropInputTiling结构体的参数说明见下表。</p><p>用户通过调用<a href="GetTiling.html">GetTiling</a>接口获取TConv3DBackpropInputTiling结构体，具体流程请参考<a href="Conv3DBackpropInput_Tiling_usage.html">Conv3DBackpropInput Tiling使用说明</a>。当前暂不支持用户自定义配置TConv3DBackpropInputTiling结构体中的参数。</p><p><strong>表1</strong> TConv3DBackpropInputTiling结构说明</p><table><thead><tr><th>参数名称</th><th>说明</th></tr></thead><tbody><tr><td>batch</td><td>输入GradOutput的N，等于卷积正向输入Input的N。</td></tr><tr><td>cin</td><td>输出GradInput的Channel，等于卷积正向输入Input的Channel。</td></tr><tr><td>cout</td><td>输入GradOutput的Channel。</td></tr><tr><td>cout1</td><td>输入GradOutput的C1，等于cout/c0。</td></tr><tr><td>cin1</td><td>输出GradInput的C1，等于卷积正向输入Input的C1，等于cin/c0。</td></tr><tr><td>cout1G</td><td>预留参数，用户无需感知。</td></tr><tr><td>cin1G</td><td>预留参数，用户无需感知。</td></tr><tr><td>c0</td><td>当前输入数据类型下C0的大小。该参数目前只支持取值为16。</td></tr><tr><td>c0Bits</td><td>任意一个数除以c0等价的右移位数，例如c0=8则c0Bits=3，c0=16则c0Bits=4。</td></tr><tr><td>dout</td><td>输入GradOutput的Depth大小，单位元素。</td></tr><tr><td>ho</td><td>输入GradOutput的Height大小，单位元素。</td></tr><tr><td>wo</td><td>输入GradOutput的Width大小，单位元素。</td></tr><tr><td>di</td><td>输出GradInput的Depth大小，等于卷积正向输入Input的Depth大小，单位元素。</td></tr><tr><td>hi</td><td>输出GradInput的Height大小，等于卷积正向输入Input的Height大小，单位元素。</td></tr><tr><td>wi</td><td>输出GradInput的Width大小，等于卷积正向输入Input的Width大小，单位元素。</td></tr><tr><td>dk</td><td>输入Weight的Depth大小，单位元素。</td></tr><tr><td>hk</td><td>输入Weight的Height大小，单位元素。</td></tr><tr><td>wk</td><td>输入Weight的Width大小，单位元素。</td></tr><tr><td>group</td><td>预留参数，用户无需感知。</td></tr><tr><td>strideD</td><td>卷积反向计算中Stride的Depth大小，单位元素。</td></tr><tr><td>strideH</td><td>卷积反向计算中StrideHeight大小，单位元素。</td></tr><tr><td>strideW</td><td>卷积反向计算中StrideWidth大小，单位元素。</td></tr><tr><td>padFront</td><td>卷积反向计算中输出矩阵GradInput Padding的Depth维度的前方向，单位元素。</td></tr><tr><td>padBack</td><td>卷积反向计算中输出矩阵GradInput Padding的Depth维度的后方向，单位元素。</td></tr><tr><td>padUp</td><td>卷积反向计算中输出矩阵GradInput Padding的Height维度的上方向，单位元素。</td></tr><tr><td>padDown</td><td>卷积反向计算中输出矩阵GradInput Padding的Height维度的下方向，单位元素。</td></tr><tr><td>padLeft</td><td>卷积反向计算中输出矩阵GradInput Padding的Width维度的左方向，单位元素。</td></tr><tr><td>padRight</td><td>卷积反向计算中输出矩阵GradInput Padding的Width维度的右方向，单位元素。</td></tr><tr><td>backpropPadTail</td><td>预留参数，用户无需感知。</td></tr><tr><td>backpropPadUp</td><td>卷积反向计算中输入矩阵GradOutput Padding的Height维度的上方向，单位元素。</td></tr><tr><td>backpropPadDown</td><td>卷积反向计算中输入矩阵GradOutput Padding的Height维度的下方向，单位元素。</td></tr><tr><td>backpropPadLeft</td><td>卷积反向计算中输入矩阵GradOutput Padding的Width维度的左方向，单位元素。</td></tr><tr><td>backpropPadRight</td><td>卷积反向计算中输入矩阵GradOutput Padding的Width维度的右方向，单位元素。</td></tr><tr><td>dilationD</td><td>卷积反向计算中Dilation的Depth大小，单位元素。</td></tr><tr><td>dilationH</td><td>卷积反向计算中Dilation的Height大小，单位元素。</td></tr><tr><td>dilationW</td><td>卷积反向计算中Dilation的Width大小，单位元素。</td></tr><tr><td>al0Pbuffer</td><td>1表示不开启DoubleBuffer，2表示开启DoubleBuffer。</td></tr><tr><td>bl0Pbuffer</td><td>1表示不开启DoubleBuffer，2表示开启DoubleBuffer。</td></tr><tr><td>cl0Pbuffer</td><td>1表示不开启DoubleBuffer，2表示开启DoubleBuffer。</td></tr><tr><td>al1Pbuffer</td><td>1表示不开启DoubleBuffer，2表示开启DoubleBuffer。</td></tr><tr><td>bl1Pbuffer</td><td>1表示不开启DoubleBuffer，2表示开启DoubleBuffer。</td></tr><tr><td>singleCoreGroup</td><td>预留参数，用户无需感知。</td></tr><tr><td>singleCoreCout</td><td>单核M方向上计算cout数据量的大小。</td></tr><tr><td>singleCoreCout1</td><td>单核上cout1的大小。</td></tr><tr><td>singleCoreCin1</td><td>单核上cin1的大小。</td></tr><tr><td>singleCoreDin</td><td>单核上Din的大小。</td></tr><tr><td>singleCoreHo</td><td>单核K方向上计算ho数据量的大小。</td></tr><tr><td>baseM</td><td>L0上M方向大小。</td></tr><tr><td>baseK</td><td>L0上K方向大小。</td></tr><tr><td>baseN</td><td>L0上N方向大小。</td></tr><tr><td>baseD</td><td>预留参数，用户无需感知。</td></tr><tr><td>baseBatch</td><td>预留参数，用户无需感知。</td></tr><tr><td>baseGroup</td><td>预留参数，用户无需感知。</td></tr><tr><td>stepM</td><td>特征矩阵在L1中缓存的buffer M方向上baseM的倍数。</td></tr><tr><td>stepN</td><td>权重矩阵在L1中缓存的buffer N方向上baseN的倍数。</td></tr><tr><td>stepKa</td><td>特征矩阵在L1中缓存的buffer K方向上baseK的倍数。</td></tr><tr><td>stepKb</td><td>权重矩阵在L1中缓存的buffer K方向上baseK的倍数。</td></tr><tr><td>stepBatch</td><td>预留参数，用户无需感知。</td></tr><tr><td>stepGroup</td><td>预留参数，用户无需感知。</td></tr><tr><td>iterateOrder</td><td>预留参数，用户无需感知。</td></tr><tr><td>hf32Flag</td><td>预留参数，用户无需感知。</td></tr><tr><td>initOutputFlag</td><td>预留参数，用户无需感知。</td></tr><tr><td>reserved</td><td>预留参数，用户无需感知。</td></tr><tr><td>singleCoreBatch</td><td>预留参数，用户无需感知。</td></tr><tr><td>singleCoreM</td><td>单核M方向上需要计算的数据量大小。</td></tr><tr><td>singleCoreCin</td><td>单核N方向上计算cin数据量的大小。</td></tr></tbody></table></article></div>',1)])])}const s=d(n,[["render",a]]);export{I as __pageData,s as default};
